    bondPortraitFallbackTried.value = {
      ...bondPortraitFallbackTried.value,
      [characterName]: false,
    };
  })();
  bondPortraitLoadTasks.set(characterName, task);
  try {
    await task;
  } finally {
    bondPortraitLoadTasks.delete(characterName);
  }
};

