  font-size: 0.62rem;
  letter-spacing: 0.22em;
  text-transform: uppercase;
}

.map-hero__title {
  margin-top: 0.35rem;
  color: rgba(247, 232, 198, 0.98);
  font-family: 'Cinzel', serif;
  font-size: clamp(1.2rem, 2vw, 1.6rem);
}

.map-hero__desc {
  margin-top: 0.52rem;
  color: rgba(237, 226, 205, 0.62);
  font-size: 0.78rem;
  line-height: 1.5;
}

.map-hero__aside {
  display: flex;
  min-width: min(100%, 24rem);
  flex-direction: column;
  align-items: stretch;
  gap: 0.55rem;
}

.map-hero__chips {
  display: flex;
  flex-wrap: wrap;
  align-items: stretch;
  justify-content: flex-start;
  gap: 0.4rem;
}

.map-hero__chip {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 0.15rem;
  min-width: 4.2rem;
  padding: 0.38rem 0.5rem;
  border-left: 1px solid rgba(220, 203, 163, 0.16);
}

.map-hero__chip-label {
  color: rgba(214, 211, 209, 0.54);
  font-size: 0.62rem;
}

.map-hero__chip-value {
  color: var(--panel-accent);
  font-family: inherit;
  font-size: 14px;
}

.map-legend {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  align-items: center;
  gap: 0.26rem 0.42rem;
  border: 1px solid rgba(28, 24, 18, 0.22);
  border-radius: 0.28rem;
  padding: 0.36rem 0.45rem;
  background: #e9e4cf;
  color: #1c1812;
}

.map-legend__title {
  grid-column: 1 / -1;
  color: rgba(28, 24, 18, 0.64);
  font-size: 0.62rem;
  font-weight: 700;
  letter-spacing: 0.12em;
}

.map-legend__item {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 0.12rem;
  white-space: nowrap;
}

.map-legend__icon {
  display: block;
  width: 1.55rem;
  height: 1.55rem;
  flex: 0 0 1.55rem;
  background-repeat: no-repeat;
