  font-weight: 600;
}

.map-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.8rem;
  padding: 0.15rem 0.1rem 0;
}

.map-summary {
  color: rgba(245, 222, 179, 0.64);
  font-size: 11px;
  letter-spacing: 0.02em;
