  background: rgba(70, 56, 40, 0.88);
  box-shadow: 0 8px 18px rgba(0, 0, 0, 0.18);
}

.map-control-btn--wide {
  min-width: 5.4rem;
}

.map-empty {
  height: 17rem;
  border: 1px dashed rgba(220, 203, 163, 0.35);
  background: rgba(18, 14, 10, 0.76);
  color: rgba(245, 222, 179, 0.55);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 13px;
}

.map-viewport {
  position: relative;
  height: min(68vh, 42rem);
  min-height: 24rem;
  border-radius: 0.45rem;
  border: 1px solid var(--panel-border);
  background: #e9e4cf;
  overflow: hidden;
  touch-action: none;
  user-select: none;
  cursor: grab;
  box-shadow: none;
}

.map-viewport:active {
  cursor: grabbing;
}

.map-viewport::before {
  display: none;
}

.map-canvas {
  position: absolute;
  left: 0;
  top: 0;
  background: #e9e4cf
    url("https://img.vinsimage.org/%E5%9C%B0%E7%89%A2/%E7%B4%A0%E6%9D%90%E5%BA%93/%E4%B8%BB%E7%95%8C%E9%9D%A2/%E5%9C%B0%E5%9B%BE%E8%83%8C%E6%99%AF.png")
    center / 100% 100% no-repeat;
}

.map-layout {
  position: absolute;
}

.map-links {
  position: absolute;
  left: 0;
  top: 0;
  pointer-events: none;
}

.map-room-cell {
  position: absolute;
  width: 62px;
  height: 62px;
  border-radius: 50%;
  border: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0.08rem;
  overflow: hidden;
  padding: 0;
  appearance: none;
  box-shadow: none;
  font-family: Georgia, 'Times New Roman', serif;
  transition:
    transform 0.18s ease,
    opacity 0.18s ease,
    filter 0.18s ease;
}

.map-room-cell--latest {
  box-shadow: none;
}

.map-room-cell:disabled {
  pointer-events: none;
  cursor: default;
  filter: saturate(0.42);
  opacity: 0.65;
}

.map-room-cell--visited {
  opacity: 0.38;
}

.map-room-cell--latest {
  opacity: 1;
  z-index: 2;
  filter: none;
}

.map-room-cell--latest:disabled {
  opacity: 1;
  filter: none;
}

.map-room-cell--available {
  cursor: pointer;
  filter: saturate(1.15);
  opacity: 1;
  outline: 2px solid rgba(82, 67, 44, 0.24);
  outline-offset: 2px;
}

.map-room-cell--start,
.map-room-cell--boss {
  width: 70px;
  height: 70px;
  font-size: 1.35rem;
}

.map-room-cell--boss {
  box-shadow: none;
}

.map-room-cell--floor {
  height: 86px;
  border-radius: 0.35rem;
  background: transparent !important;
  border-color: transparent;
  color: #3d3427 !important;
  gap: 0.18rem;
  padding: 0.35rem 0.3rem;
}

.map-room-cell--available:hover,
.map-room-cell--available:focus-visible {
  transform: translateY(-2px) scale(1.08);
  background: radial-gradient(circle, rgba(28, 24, 18, 0.16), rgba(28, 24, 18, 0.02) 68%, transparent 70%) !important;
  outline-color: rgba(82, 67, 44, 0.8);
  box-shadow:
    0 0 0 4px rgba(245, 229, 190, 0.5),
    0 2px 10px rgba(57, 49, 37, 0.38);
}

.map-room-cell--available:hover .map-room-icon,
.map-room-cell--available:focus-visible .map-room-icon {
  transform: scale(1.12);
  filter: brightness(0.62) drop-shadow(0 2px 2px rgba(28, 24, 18, 0.4));
}

.map-room-cell--latest .map-room-icon {
  animation: map-current-room-pulse 2.4s ease-in-out infinite;
  filter: drop-shadow(0 0 3px rgba(255, 238, 190, 0.32)) drop-shadow(0 2px 3px rgba(28, 24, 18, 0.28));
}

.map-room-cell--latest .map-room-pulse {
  display: none;
}

.map-room-pulse {
  position: absolute;
  inset: 0;
  border-radius: inherit;
  border: 1px dashed rgba(85, 68, 43, 0.62);
  pointer-events: none;
}

.map-room-icon {
  position: relative;
  display: block;
  width: 54px;
  height: 54px;
  flex: 0 0 54px;
  background-repeat: no-repeat;
  background-size: 400% 200%;
  transition:
    transform 0.22s ease,
    filter 0.22s ease;
}

@keyframes map-current-room-pulse {
  0%,
  100% {
    transform: scale(0.96);
  }

  50% {
    transform: scale(1.08);
  }
}

.map-room-label {
  position: relative;
  max-width: 92%;
  font-size: 0.6rem;
  line-height: 1.1;
  text-align: center;
  opacity: 0.86;
  overflow-wrap: anywhere;
}

.map-room-cell:not(.map-room-cell--floor) .map-room-label {
  display: none;
}

.bond-list {
