}

.chest-reward-slot.is-intro .chest-reward-pillar {
  opacity: 0;
  animation:
    chest-reward-pillar-rise 360ms cubic-bezier(0.22, 0.8, 0.28, 1) 450ms both,
    chest-reward-pillar-pulse 2.4s ease-in-out 810ms infinite;
}

.chest-reward-ground-ring {
  left: 50%;
  bottom: 0.22rem;
  width: 6.7rem;
  height: 1.25rem;
