.shop-panel-head h2 {
  margin: 0 0 4px;
  font: 36px/1.2 'MagicBookTitle', 'KaiTi', serif;
  color: #f8d39c;
  text-shadow: 0 0 10px rgba(182, 107, 30, 0.33);
}

.shop-panel-head span:not(.shop-panel-compass) {
  font: 12px/1.1 Georgia, serif;
  color: #bc9161;
}

.shop-goods-grid {
  display: grid;
  flex: 1;
  min-height: 0;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  grid-template-rows: repeat(2, minmax(0, 1fr));
  grid-auto-rows: minmax(180px, 1fr);
  align-content: start;
  gap: 16px 18px;
  overflow-y: auto;
  margin: 16px -5px 10px;
  padding: 7px 10px 8px 5px;
}

.shop-item-card {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-end;
  width: 100%;
  min-width: 0;
  height: 100%;
  padding: 19px 11px 17px;
  border: 1px solid rgba(180, 123, 61, 0.42);
  border-radius: 2px;
  background: linear-gradient(180deg, rgba(22, 15, 14, 0.16), rgba(2, 2, 4, 0.35));
  color: #eee5d6;
  cursor: pointer;
  transition: transform 0.2s ease, filter 0.2s ease, opacity 0.2s ease;
}

.shop-item-card::after {
  position: absolute;
  inset: -7px;
  background: var(--shop-frame-image) center / 100% 100% no-repeat;
  opacity: 0.8;
  pointer-events: none;
  content: '';
}

.shop-item-card:hover:not(:disabled),
.shop-item-card:focus-visible {
  transform: translateY(-2px);
  filter: brightness(1.24);
}

.shop-item-card.is-sold {
  opacity: 0.38;
  cursor: not-allowed;
}

.inventory-relic {
  min-width: 0;
  color: #a6bad8;
}

.inventory-relic-icon-wrap {
  position: relative;
  display: grid;
  flex: none;
  width: 56px;
  height: 56px;
  place-items: center;
}

.inventory-relic-icon-wrap::before {
  position: absolute;
  inset: 2px;
  border: 1px solid currentColor;
  border-radius: 50%;
  opacity: 0.25;
  box-shadow: 0 0 10px currentColor, inset 0 0 10px currentColor;
  content: '';
}

.inventory-relic-icon {
  width: 36px;
  height: 36px;
  stroke-width: 1.1;
  filter: drop-shadow(0 0 6px currentColor);
}

.inventory-relic-count {
  position: absolute;
  right: -3px;
  bottom: 0;
  padding: 0 2px;
  border: 1px solid currentColor;
  border-radius: 2px;
  background: #15121a;
  font: 10px/1.3 var(--font-ui);
}

.inventory-relic-name {
  width: 100%;
  min-height: 3em;
  margin-top: 6px;
  font: 11px/1.5 var(--font-heading);
  text-align: center;
  overflow-wrap: anywhere;
}

.shop-item-icon-wrap {
  position: relative;
  display: grid;
  flex: 1;
  width: 100%;
  min-height: 0;
  place-items: center;
  color: #a6bad8;
}

.shop-item-icon-wrap::before {
  position: absolute;
  width: 118px;
  height: 118px;
  border: 1px solid currentColor;
  border-radius: 50%;
  opacity: 0.25;
  box-shadow: 0 0 14px currentColor, inset 0 0 14px currentColor;
  content: '';
}

.inventory-relic.is-rare,
.shop-item-card.is-rare .shop-item-icon-wrap {
  color: #c59dbd;
}

.inventory-relic.is-legendary,
.shop-item-card.is-legendary .shop-item-icon-wrap {
  color: #e7bb76;
}

.shop-item-icon {
  width: 79px;
  height: 79px;
  stroke-width: 1.1;
  filter: drop-shadow(0 0 13px currentColor);
}

.shop-item-count {
  position: absolute;
  right: 3px;
  bottom: 8px;
  font: 16px/1 Georgia, serif;
  color: #f4ede1;
}

.shop-item-name {
  flex: none;
  width: 100%;
  display: grid;
  height: 2.8em;
  margin: 4px 0 8px;
  padding: 0 2px;
  place-items: center;
  font: 15px/1.25 'MagicBookTitle', 'KaiTi', serif;
  text-align: center;
  overflow-wrap: anywhere;
  text-shadow: 0 1px 4px #000;
}

.shop-item-price {
  display: flex;
  flex: none;
  align-items: center;
  justify-content: center;
  gap: 10px;
  width: 78%;
  height: 34px;
  border: 1px solid rgba(184, 132, 65, 0.62);
  border-radius: 2px;
  background: rgba(12, 9, 7, 0.23);
  color: #e8bb7b;
  font: 16px/1 Georgia, serif;
}

.shop-item-price svg {
  width: 18px;
  height: 18px;
}

.shop-item-confirm-hint {
  position: absolute;
  z-index: 1;
  bottom: 12px;
  left: 50%;
  transform: translateX(-50%);
  width: max-content;
  max-width: 90%;
  padding: 4px 8px;
  border: 1px solid #d5ac74;
  background: #0c0a09;
  color: #f8dab0;
  font: 12px/1.2 'MagicBookTitle', 'KaiTi', serif;
  pointer-events: none;
}

.shop-empty {
  grid-column: 1 / -1;
  align-self: center;
  text-align: center;
  font: 22px/1.5 'MagicBookTitle', 'KaiTi', serif;
  color: #c3a987;
}

.shop-panel-foot {
  position: relative;
  display: flex;
  flex: none;
  align-items: center;
  justify-content: flex-end;
  gap: 20px;
  height: 84px;
  padding: 5px 38px 17px 0;
  border-top: 1px solid rgba(195, 143, 74, 0.58);
}

.shop-panel-foot::before {
  top: -4px;
  bottom: auto;
}

.shop-rob-btn,
.shop-exit-btn {
  position: relative;
  z-index: 1;
  height: 50px;
  border: 1px solid #9f6e37;
  border-radius: 3px;
  background: linear-gradient(90deg, rgba(21, 14, 10, 0.26), rgba(74, 48, 25, 0.44) 50%, rgba(21, 14, 10, 0.26));
  box-shadow: inset 0 0 10px rgba(154, 99, 43, 0.18);
  color: #f1c384;
  font: 23px/1 'MagicBookTitle', 'KaiTi', serif;
  cursor: pointer;
  transition: background-color 0.2s ease, box-shadow 0.2s ease;
}

.shop-rob-btn {
  width: 160px;
}

.shop-exit-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 17px;
  width: 245px;
}

.shop-exit-btn svg {
  width: 22px;
  height: 22px;
}

.shop-rob-btn:hover:not(:disabled),
.shop-exit-btn:hover:not(:disabled) {
  background-color: rgba(163, 99, 41, 0.18);
  box-shadow: inset 0 0 12px rgba(213, 153, 79, 0.35);
}

.shop-rob-btn:disabled,
.shop-exit-btn:disabled {
  cursor: not-allowed;
  filter: grayscale(0.5);
}

.ui-viewport--compact-portrait .shop-brand {
